div.style:
display:none; position:fixed; top:30%; left:50%; transform:translate(-50%, -50%);
                             background-color:#fff; padding:20px; box-shadow:0 0 10px #666; z-index:1000;
                             border-radius:8px; border:1px solid #ccc; text-align:center;

body.script:
let currentRowToClose = null;

function showCloseOptions(rowNumber) {
    currentRowToClose = rowNumber;
    document.getElementById("closeModal").style.display = "block";}

function hideCloseOptions() {
    document.getElementById("closeModal").style.display = "none";
    currentRowToClose = null;}

function submitClose(status) {
    if (currentRowToClose !== null) {
        window.location.href = `/close/${currentRowToClose}?status=${encodeURIComponent(status)}`;}}


let currentRowForStatus = null;

function showStatusOptions(rowNumber) {
    currentRowForStatus = rowNumber;
    document.getElementById("statusModal").style.display = "block";}

function hideStatusOptions() {
    document.getElementById("statusModal").style.display = "none";
    currentRowForStatus = null;}

function submitStatus(status) {
    if (currentRowForStatus !== null) {        
        window.location.href = `/close/${currentRowForStatus}?status=${encodeURIComponent(status)}`;}
    }

function toggleForm() {
    var f = document.getElementById("formContainer");
    f.style.display = f.style.display === "none" ? "block" : "none";
}
